//! The Rust side: one file of `extern "system"` entry points for every class, which awnative's
//! build.rs writes into OUT_DIR and its `boundary` module includes. Each entry point reads its
//! strings, calls the hand-written function, and lets `boundary::call` hand the result back to
//! Kotlin or throw its error.

use crate::format::{rust_body, rust_comment, rust_doc, rust_signature};
use crate::{Class, Method, Param, jni_name, snake_case};

const HEADER: &str = "\
// Generated by lib/rust/crates/boundary from its declarations, src/declarations. Do not edit:
// awnative's build.rs writes this file into cargo's OUT_DIR, and src/boundary.rs includes it.
";

/// The `jni_sys` names the entry points may use, in the order rustfmt sorts them.
const JNI_NAMES: [&str; 6] = ["JNIEnv", "jboolean", "jclass", "jint", "jlong", "jstring"];

/// The entry points for every method of `classes`, as one file.
pub fn rust_file(classes: &[Class]) -> String {
    let mut text = String::from(HEADER);
    text.push_str(&format!(
        "\nuse jni_sys::{{{}}};\n\nuse crate::boundary::call;\n",
        jni_imports(classes).join(", ")
    ));
    for class in classes {
        let module = class.module;
        let about = format!(
            "{}, declared in src/declarations/{module}.rs, calls crate::{module}.",
            class.name
        );
        text.push('\n');
        text.push_str(&rust_comment(&about, ""));
        for method in class.methods {
            text.push('\n');
            text.push_str(&entry_point(class, method));
        }
    }
    text
}

/// The `jni_sys` names the entry points for `classes` use.
fn jni_imports(classes: &[Class]) -> Vec<&'static str> {
    let methods = || classes.iter().flat_map(|class| class.methods);
    let used = |name: &str| {
        name == "JNIEnv"
            || name == "jclass"
            || methods().any(|method| {
                method.returns.jni() == name || method.params.iter().any(|(_, p)| p.jni() == name)
            })
    };
    JNI_NAMES.into_iter().filter(|name| used(name)).collect()
}

fn entry_point(class: &Class, method: &Method) -> String {
    let mut text = rust_doc(method.doc, "");
    text.push_str("#[unsafe(no_mangle)]\n");
    let mut params = vec!["env: *mut JNIEnv".to_owned(), "_: jclass".to_owned()];
    for (name, param) in method.params {
        params.push(format!("{}: {}", snake_case(name), param.jni()));
    }
    text.push_str(&rust_signature(
        &format!("pub extern \"system\" fn {}", jni_name(class, method)),
        &params,
        method.returns.jni(),
    ));
    let mut lets = Vec::new();
    let mut args = Vec::with_capacity(method.params.len());
    for (name, param) in method.params {
        let rust = snake_case(name);
        match param {
            Param::Int | Param::Long => args.push(rust),
            Param::String => {
                args.push(format!("&{rust}"));
                lets.push((
                    rust.clone(),
                    format!("env.read_string({rust}, \"{name}\")?"),
                ));
            }
        }
    }
    let callee = format!("crate::{}::{}", class.module, snake_case(method.name));
    text.push_str("    // SAFETY: the JVM passes its environment for this call.\n");
    text.push_str(&rust_body(&lets, &callee, &args));
    text.push_str("}\n");
    text
}
